import json
from pathlib import Path
root=Path('/workspace/planning/trading-model')
a=json.loads((root/'review/source_inventory.json').read_text())
def fmt(r):return ', '.join(f'{lo}-{hi}' for lo,hi in r) if r else 'pending'
def count(r):return len({i for lo,hi in r for i in range(lo,hi+1)})
lines=['# Source review ledger','','Status: supplied-source review complete. Every supplied PDF page received full textual and actual visual review; every supplied text/source passage was read to its end. Intrinsically cropped/unreadable content and absent attachments remain explicit below. No empirical trading tests, production implementation or trained edge is claimed. Current design focus is Context, Location and supporting layers; detailed Response development remains deferred.','','Review conducted 2026-09-05–06 UTC. Bundle README describes a 2026-09-06 upload; preserve the timestamp discrepancy as provenance.','','## Reconciliation','','52 actual bundle files: 50 entries in the current manifest and two extra controls README.md and SOURCE_MANIFEST.json. The initial manifest contained 49 entries; its current version adds only the user-supplied conversations/Design robust feature levels.md received during review. The original 49 entries remain unchanged; all 50 current entries match file hashes/sizes. The control-file change and both verified versions are recorded in review/source-control-versions/version_reconciliation.json. No source was rewritten by this task. 39 PDFs, 580 pages. ZIP safely extracted to isolated review directory: 83 regular text/source members, 51,659 lines; no binary assets. All 83 members were statically read; no bundled code was executed.','','## Exact file coverage','','| Exact path | Extent | Text reviewed | Visual reviewed | Findings and unresolved |','|---|---|---|---|---|']
for v in a:
 extent=str(v.get('pages'))+' pages' if v.get('pages') else str(v.get('lines'))+' lines' if v.get('lines') is not None else 'archive/image'
 visual=fmt(v['visual_reviewed']) if v.get('pages') or v['relative_path'].endswith('.webp') else 'N/A (see attachment limitations)'
 text_status='All 83 members; see itemized coverage below' if v['relative_path'].endswith('.zip') else fmt(v['text_reviewed'])
 note=v.get('finding_ids','')+'; '+v.get('unresolved','')
 lines.append(f"| `{v['path']}` | {extent} | {text_status} | {visual} | {note.strip('; ')} |")
pdfs=[v for v in a if v.get('pages')]
conversations=[v for v in a if v['relative_path'].startswith('conversations/') or v['relative_path']=='jumbo/JJumbo_Conversation_Export.md']
lines+=['','## Reconciled review totals','',f"PDF text pages actually reviewed: {sum(count(v['text_reviewed']) for v in pdfs)}/580. PDF pages actually viewed: {sum(count(v['visual_reviewed']) for v in pdfs)}/580. All supplied pages are accounted for; original-image extraction/enlargement supplemented tiny chart/diagram review.",'',f"Historical conversations: {len(conversations)} files, {sum(v['lines'] for v in conversations):,} supplied lines, all read end-to-end. This includes both user messages in Develop Trading Model and the added Design robust feature levels conversation. Mermaid source and attachment descriptions were read; absent original pixels/tool results remain absent.",'','The standalone reference WEBP was actually viewed in full and in three enlarged panels. Two standalone indicator sources total 2,009 lines, all read. README/manifest and inventory/pull-list files were fully read. The original retrieved Jumbo tweet archive contains 66 posts across 48 pages; this is full coverage of the supplied artifact, not the author’s entire work.','','ZIP member review is itemized below and in review/zip_inventory.json. Source passage/diagram findings are recorded with stable IDs in SOURCE_FINDINGS_AND_CONFLICTS.md. Missing referenced assets and partially unreadable source digits remain explicit even when supplied page review is complete.']
z=json.loads((root/'review/zip_inventory.json').read_text())
lines += ['', '## Extracted ZIP member coverage', '', '| Exact isolated member path | Lines | Text reviewed | Findings | Visual content |', '|---|---|---|---|---|']
for v in z:
 lines.append(f"| `{v['path']}` | {v['lines']} | {fmt(v['text_reviewed'])} | {v.get('finding_ids','pending')} | No embedded images; drawing logic reviewed as source when text complete |")
lines += ['', f"ZIP members fully read: {sum(count(v['text_reviewed'])==v['lines'] for v in z)}/{len(z)}; lines actually read: {sum(count(v['text_reviewed']) for v in z)}/{sum(v['lines'] for v in z)}. Static inspection, no Pine code execution."]
ext=json.loads((root/'review/external/skylit/inventory.json').read_text())['pages']
imgs=json.loads((root/'review/external/skylit/images.json').read_text())
full=[v for v in ext if v.get('text_reviewed')]
lines += ['', '## External Skylit documentation accounting', '', f"Research date 2026-09-06 UTC. All {len(ext)} indexed pages were fetched successfully and accounted for: {len(full)} full narrative/text reads and {len(ext)-len(full)} focused generated-API semantic reviews. Focused review covered endpoint descriptions, defaults, field meanings, constraints, aggregation, timing and availability; it does not claim every repeated generated schema/example/boilerplate line was read verbatim. All {sum(bool(v.get('viewed')) for v in imgs)}/{len(imgs)} retrieved substantive images were actually viewed, with originals enlarged where needed. Findings and exact URLs are in EXTERNAL_RESEARCH.md; raw captures/hashes and readable versions are retained under review/external/skylit.", '', '| Page ID and exact URL | Supplied capture lines | Review method | Image coverage |', '|---|---|---|---|']
for v in ext:
 im=[x for x in imgs if x.get('page_id')==v['id']]
 method='Full readable text' if v.get('text_reviewed') else 'Focused API semantics; generated boilerplate not fully read'
 lines.append(f"| [{v['id']}]({v['url']}) | {v.get('lines')} | {method} | {len(im)} images, {sum(bool(x.get('viewed')) for x in im)} viewed |")
lines += ['', 'Official account/provider/method sources were read to the specific relevant passages described in ACCOUNT_CONSTRAINTS.md and EXTERNAL_RESEARCH.md (TECH-01–18). Their scope is focused factual/method research, not a claim of full-text review of every referenced book/paper/site. Unavailable original Garman–Klass full text and proprietary formulas are disclosed. No external account actions or messages were sent.', '', '## Completion boundary', '', 'No supplied page, passage or source member remains unread. Cropped/degraded originals, omitted attachments/videos, unprovided formulas and truncated Pine file tails cannot be reconstructed; exact limitations remain in the file rows and OPEN_QUESTIONS_AND_RISKS.md. Exhaustive document review is distinct from proportionate market-data auditing: see DATA_CAPABILITY_AUDIT.md for the actual sampled rows/files and unrun validation work.']
(root/'SOURCE_REVIEW_LEDGER.md').write_text('\n'.join(lines)+'\n')
